  1 | import { useCallback, useRef, useState } from "react";
  2 | import type { Track } from "../types";
  3 | 
  4 | interface PlaylistProps {
  5 |   tracks: Track[];
  6 |   currentTrackId: string | null;
  7 |   isPlaying: boolean;
  8 |   onSelectTrack: (track: Track) => void;
  9 |   onReorderPlaylist?: (tracks: Track[]) => void;
 10 | }
 11 | 
 12 | function formatDuration(seconds: number): string {
 13 |   const mins = Math.floor(seconds / 60);
 14 |   const secs = Math.floor(seconds % 60);
 15 |   return `${mins}:${secs.toString().padStart(2, "0")}`;
 16 | }
 17 | 
 18 | export function Playlist({
 19 |   tracks,
 20 |   currentTrackId,
 21 |   isPlaying,
 22 |   onSelectTrack,
 23 |   onReorderPlaylist,
 24 | }: PlaylistProps) {
 25 |   const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);
 26 |   const dragItemIndex = useRef<number | null>(null);
 27 | 
 28 |   const handleDragStart = useCallback(
 29 |     (e: React.DragEvent<HTMLLIElement>, index: number) => {
 30 |       dragItemIndex.current = index;
 31 |       e.dataTransfer.effectAllowed = "move";
 32 |       e.dataTransfer.setData("text/plain", String(index));
 33 |       // Add a slight delay so the drag image shows properly
 34 |       e.currentTarget.classList.add("dragging");
 35 |     },
 36 |     []
 37 |   );
 38 | 
 39 |   const handleDragEnd = useCallback(
 40 |     (e: React.DragEvent<HTMLLIElement>) => {
 41 |       e.currentTarget.classList.remove("dragging");
 42 |       dragItemIndex.current = null;
 43 |       setDragOverIndex(null);
 44 |     },
 45 |     []
 46 |   );
 47 | 
 48 |   const handleDragOver = useCallback(
 49 |     (e: React.DragEvent<HTMLLIElement>, index: number) => {
 50 |       e.preventDefault();
 51 |       e.dataTransfer.dropEffect = "move";
 52 |       setDragOverIndex(index);
 53 |     },
 54 |     []
 55 |   );
 56 | 
 57 |   const handleDragLeave = useCallback(() => {
 58 |     setDragOverIndex(null);
 59 |   }, []);
 60 | 
 61 |   const handleDrop = useCallback(
 62 |     (e: React.DragEvent<HTMLLIElement>, dropIndex: number) => {
 63 |       e.preventDefault();
 64 |       const fromIndex = dragItemIndex.current;
 65 |       if (fromIndex === null || fromIndex === dropIndex) {
 66 |         setDragOverIndex(null);
 67 |         return;
 68 |       }
 69 | 
 70 |       const reordered = [...tracks];
 71 |       const [movedItem] = reordered.splice(fromIndex, 1);
 72 |       reordered.splice(dropIndex, 0, movedItem);
 73 | 
 74 |       onReorderPlaylist?.(reordered);
 75 |       dragItemIndex.current = null;
 76 |       setDragOverIndex(null);
 77 |     },
 78 |     [tracks, onReorderPlaylist]
 79 |   );
 80 | 
 81 |   return (
 82 |     <section className="playlist-panel">
 83 |       <div className="panel-header">PLAYLIST</div>
 84 |       <ul className="playlist">
 85 |         {tracks.length === 0 ? (
 86 |           <li className="playlist-item playlist-empty">
 87 |             Nenhuma música na playlist
 88 |           </li>
 89 |         ) : (
 90 |           tracks.map((track, index) => (
 91 |             <li
 92 |               key={track.id}
 93 |               className={`playlist-item ${
 94 |                 track.id === currentTrackId ? "active" : ""
 95 |               } ${dragOverIndex === index ? "drag-over" : ""}`}
 96 |               draggable
 97 |               onClick={() => onSelectTrack(track)}
 98 |               onDragStart={(e) => handleDragStart(e, index)}
 99 |               onDragEnd={handleDragEnd}
100 |               onDragOver={(e) => handleDragOver(e, index)}
101 |               onDragLeave={handleDragLeave}
102 |               onDrop={(e) => handleDrop(e, index)}
103 |               title={`${track.title}${track.artist ? ` — ${track.artist}` : ""}`}
104 |             >
105 |               <span className="playlist-item-drag-handle" title="Arrastar para reordenar">
106 |                 ⠿
107 |               </span>
108 |               <span className="playlist-item-icon">
109 |                 {track.id === currentTrackId && isPlaying ? "▶" : "🎵"}
110 |               </span>
111 |               <span className="playlist-item-title">{track.title}</span>
112 |               {track.artist && (
113 |                 <span className="playlist-item-artist">{track.artist}</span>
114 |               )}
115 |               <span className="playlist-item-duration">
116 |                 {formatDuration(track.duration)}
117 |               </span>
118 |             </li>
119 |           ))
120 |         )}
121 |       </ul>
122 |       <div className="panel-footer">
123 |         <span>{tracks.length} música{tracks.length !== 1 ? "s" : ""}</span>
124 |         <span>
125 |           {tracks.reduce((acc, t) => acc + t.duration, 0) > 0
126 |             ? formatDuration(tracks.reduce((acc, t) => acc + t.duration, 0))
127 |             : "—:—:—"}
128 |         </span>
129 |       </div>
130 |     </section>
131 |   );
132 | }
